#requires -version 5.1
[CmdletBinding()]
param(
    [string]$InstallRoot = (Join-Path $env:LOCALAPPDATA 'Programs\WindowsLocalNetworkPolicyManager'),
    [switch]$ResetRules,
    [switch]$SetupMcp
)

$ErrorActionPreference = 'Stop'
$PackageVersion = '0.2.0-preview.1'
$SourceBranch = 'feature/auto-discovery-mcp'
$GeneratedAt = '2026-09-23T12:23:46.094Z'

$Files = @{
    'NetworkPolicyManager\\Launcher.cs' = ''
    'NetworkPolicyManager\\app.manifest' = ''
    'NetworkPolicyManager\\build.ps1' = ''
    'NetworkPolicyManager\\network-rules.json' = ''
    'NetworkPolicyManager\\test.ps1' = ''
    'NetworkPolicyManager\\本地网络策略管理器.ps1' = ''
    'NetworkPolicyManager\\README.md' = ''
    'NetworkPolicyManager\\UI_STYLE.md' = ''
    'NetworkPolicyManager\\mcp\\README.md' = ''
    'NetworkPolicyManager\\mcp\\package.json' = ''
    'NetworkPolicyManager\\mcp\\setup.ps1' = ''
    'NetworkPolicyManager\\mcp\\tsconfig.json' = ''
    'NetworkPolicyManager\\mcp\\src\\index.ts' = ''
}

function Write-PackageFile {
    param([string]$RelativePath, [string]$Base64)
    $target = Join-Path $InstallRoot $RelativePath
    $parent = Split-Path -Parent $target
    if (-not (Test-Path -LiteralPath $parent)) {
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
    }

    if ($RelativePath -eq 'NetworkPolicyManager\network-rules.json' -and
        (Test-Path -LiteralPath $target) -and -not $ResetRules) {
        Write-Host "保留现有规则：$target" -ForegroundColor DarkYellow
        return
    }

    [IO.File]::WriteAllBytes($target, [Convert]::FromBase64String($Base64))
}

Write-Host "Windows Local Network Policy Manager $PackageVersion" -ForegroundColor Cyan
Write-Host "安装目录：$InstallRoot"
Write-Host "来源分支：$SourceBranch"
Write-Host ''

if (Test-Path -LiteralPath $InstallRoot) {
    $existingRules = Join-Path $InstallRoot 'NetworkPolicyManager\network-rules.json'
    if (Test-Path -LiteralPath $existingRules) {
        $backupDir = Join-Path $InstallRoot 'backup'
        New-Item -ItemType Directory -Path $backupDir -Force | Out-Null
        $backupPath = Join-Path $backupDir ('network-rules-before-update-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.json')
        Copy-Item -LiteralPath $existingRules -Destination $backupPath -Force
        Write-Host "已备份现有规则：$backupPath" -ForegroundColor DarkYellow
    }
}
New-Item -ItemType Directory -Path $InstallRoot -Force | Out-Null

foreach ($entry in $Files.GetEnumerator()) {
    Write-PackageFile -RelativePath $entry.Key -Base64 $entry.Value
}

$uninstallText = @'
[CmdletBinding()]
param([switch]$Force)
$ErrorActionPreference = ''Stop''
$root = $PSScriptRoot
$state = Join-Path $root ''NetworkPolicyManager\manager-state.json''
if ((Test-Path -LiteralPath $state) -and -not $Force) {
    $text = Get-Content -LiteralPath $state -Raw -Encoding UTF8
    if (-not [string]::IsNullOrWhiteSpace($text) -and $text.Trim() -ne ''[]'') {
        Write-Host ''检测到仍有本程序管理的网络策略。请先在程序中撤销已接管规则，再卸载。'' -ForegroundColor Yellow
        Write-Host ''如确认系统路由已自行处理，可使用：.\卸载.ps1 -Force''
        exit 2
    }
}
$desktop = [Environment]::GetFolderPath(''Desktop'')
$shortcut = Join-Path $desktop ''本地网络策略管理器.lnk''
Remove-Item -LiteralPath $shortcut -Force -ErrorAction SilentlyContinue
$parent = Split-Path -Parent $root
$leaf = Split-Path -Leaf $root
$cmd = "Start-Sleep -Milliseconds 500; Remove-Item -LiteralPath ''$root'' -Recurse -Force"
Start-Process powershell.exe -ArgumentList @(''-NoProfile'',''-ExecutionPolicy'',''Bypass'',''-Command'',$cmd) -WindowStyle Hidden
Write-Host "已安排删除：$root" -ForegroundColor Green

'@
Set-Content -LiteralPath (Join-Path $InstallRoot '卸载.ps1') -Value $uninstallText -Encoding UTF8

$validateText = @'
@echo off
chcp 65001 >nul
setlocal
cd /d "%~dp0"
powershell.exe -NoProfile -ExecutionPolicy Bypass -File ".\NetworkPolicyManager\test.ps1" -Ui
echo.
echo 验证结束。请把窗口输出和 NetworkPolicyManager\ui-smoke-test.png 返回给我。
pause

'@
Set-Content -LiteralPath (Join-Path $InstallRoot '验证预览版.cmd') -Value $validateText -Encoding UTF8

$versionInfo = [pscustomobject]@{
    Version = $PackageVersion
    SourceBranch = $SourceBranch
    GeneratedAt = $GeneratedAt
    InstalledAt = (Get-Date).ToString('o')
} | ConvertTo-Json -Depth 4
Set-Content -LiteralPath (Join-Path $InstallRoot 'preview-version.json') -Value $versionInfo -Encoding UTF8

$manager = Join-Path $InstallRoot 'NetworkPolicyManager\本地网络策略管理器.ps1'
Write-Host ''
Write-Host '执行只读 SelfTest...' -ForegroundColor Cyan
$self = & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $manager -SelfTest 2>&1
if ($LASTEXITCODE -ne 0 -or ($self -join [Environment]::NewLine) -notmatch 'SELF_TEST_OK') {
    throw "SelfTest 失败：$($self -join [Environment]::NewLine)"
}
Write-Host ($self -join [Environment]::NewLine) -ForegroundColor Green

Write-Host '编译启动 EXE...' -ForegroundColor Cyan
$build = Join-Path $InstallRoot 'NetworkPolicyManager\build.ps1'
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $build
if ($LASTEXITCODE -ne 0) { throw 'EXE 构建失败。' }

$exe = Join-Path $InstallRoot '本地网络策略管理器.exe'
if (-not (Test-Path -LiteralPath $exe)) { throw "未生成 EXE：$exe" }

$desktop = [Environment]::GetFolderPath('Desktop')
$shortcutPath = Join-Path $desktop '本地网络策略管理器.lnk'
$shell = New-Object -ComObject WScript.Shell
$shortcut = $shell.CreateShortcut($shortcutPath)
$shortcut.TargetPath = $exe
$shortcut.WorkingDirectory = $InstallRoot
$shortcut.Description = 'Windows 本地网络策略管理器（预览版）'
$shortcut.Save()

if ($SetupMcp) {
    Write-Host '安装 MCP 依赖...' -ForegroundColor Cyan
    $mcpSetup = Join-Path $InstallRoot 'NetworkPolicyManager\mcp\setup.ps1'
    & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $mcpSetup
    if ($LASTEXITCODE -ne 0) { throw 'MCP 安装/类型检查失败。' }
}

Write-Host ''
Write-Host '安装完成。' -ForegroundColor Green
Write-Host "桌面快捷方式：$shortcutPath"
Write-Host "验证脚本：$(Join-Path $InstallRoot '验证预览版.cmd')"
Write-Host "卸载脚本：$(Join-Path $InstallRoot '卸载.ps1')"
Write-Host ''
Write-Host '建议先双击“本地网络策略管理器”查看自动识别结果，不要立即点击“应用全部”。' -ForegroundColor Yellow
